using System.Text.RegularExpressions;

namespace ShipRight.Modules.Setup;

/// <summary>File-system helpers shared by the stack providers.</summary>
internal static class StackFiles
{
    public const string GeneratedHeader =
        "# Generated by ShipRight. Safe to edit - ShipRight never overwrites an existing Dockerfile.";

    private static readonly HashSet<string> SkippedFolders =
        new(StringComparer.OrdinalIgnoreCase) { "node_modules", "bin", "obj", "dist", "packages" };

    /// <summary>Files under <paramref name="root"/> (up to <paramref name="maxDepth"/> folders down) matching the predicate, in a stable order.</summary>
    public static List<string> Find(string root, Func<string, bool> fileNameMatches, int maxDepth)
    {
        var results = new List<string>();
        Walk(root, 0, maxDepth, fileNameMatches, results);
        results.Sort(StringComparer.OrdinalIgnoreCase);
        return results;
    }

    private static void Walk(string dir, int depth, int maxDepth, Func<string, bool> match, List<string> results)
    {
        try
        {
            foreach (var file in Directory.GetFiles(dir))
                if (match(Path.GetFileName(file))) results.Add(file);

            if (depth >= maxDepth) return;
            foreach (var sub in Directory.GetDirectories(dir))
            {
                var name = Path.GetFileName(sub);
                if (name.StartsWith('.') || SkippedFolders.Contains(name)) continue;
                Walk(sub, depth + 1, maxDepth, match, results);
            }
        }
        catch (UnauthorizedAccessException) { /* unreadable folders are simply not searched */ }
        catch (DirectoryNotFoundException) { }
    }

    /// <summary>The Dockerfile in <paramref name="dir"/> (any letter case), or null.</summary>
    public static string? DockerfileIn(string dir)
    {
        try
        {
            return Directory.GetFiles(dir)
                .FirstOrDefault(f => Path.GetFileName(f).Equals("dockerfile", StringComparison.OrdinalIgnoreCase));
        }
        catch (IOException) { return null; }
        catch (UnauthorizedAccessException) { return null; }
    }

    public static bool IsSameOrBelow(string root, string dir) =>
        Path.GetRelativePath(root, dir) is var rel && !rel.StartsWith("..") && !Path.IsPathRooted(rel);

    /// <summary>Path of <paramref name="path"/> relative to <paramref name="baseDir"/>, with forward slashes.</summary>
    public static string RelativeTo(string baseDir, string path) =>
        Path.GetRelativePath(baseDir, path).Replace('\\', '/');

    /// <summary>"2.4-beta.1" → "2.4.0", "v1" → "1.0.0"; null when there is no leading number.</summary>
    public static string? NormalizeVersion(string? raw)
    {
        if (string.IsNullOrWhiteSpace(raw)) return null;
        var m = Regex.Match(raw.Trim(), @"^v?(\d+)(?:\.(\d+))?(?:\.(\d+))?");
        if (!m.Success) return null;
        return $"{m.Groups[1].Value}.{(m.Groups[2].Success ? m.Groups[2].Value : "0")}.{(m.Groups[3].Success ? m.Groups[3].Value : "0")}";
    }

    public static string Lines(params string[] lines) => string.Join("\n", lines) + "\n";
}
